package com.ftk.tpip.control.api.catalog;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.*;import com.ftk.tpip.catalog.domain.model.*;import com.ftk.tpip.control.application.catalog.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.net.URI;import java.time.Instant;import java.util.List;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/control/v1/contracts") public class CanonicalContractController{private final CanonicalContractApplicationService s;private final ObjectMapper mapper;public CanonicalContractController(CanonicalContractApplicationService s,ObjectMapper mapper){this.s=s;this.mapper=mapper;}
@PostMapping public ResponseEntity<Response> create(@Valid@RequestBody Create r,@RequestHeader("X-Operator")@NotBlank@Size(max=100)String actor){var c=s.create(r.operationId,r.contractCode,r.contractName,r.contractKind,r.description,actor);return ResponseEntity.created(URI.create("/control/v1/contracts/"+c.id())).body(Response.from(c));}@GetMapping("/{id}")public Response get(@PathVariable@Min(1)long id){return Response.from(s.get(id));}@GetMapping public Page list(@RequestParam(required=false)@Min(1)Long operationId,@RequestParam(required=false)ContractKind contractKind,@RequestParam(required=false)String keyword,@RequestParam(required=false)CanonicalContractStatus status,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(200)int size){var p=s.list(operationId,contractKind,keyword,status,page,size);return new Page(p.items().stream().map(Response::from).toList(),page,size,p.totalElements());}@PutMapping("/{id}")public Response update(@PathVariable@Min(1)long id,@Valid@RequestBody Update r,@RequestHeader("X-Operator")@NotBlank@Size(max=100)String actor){return Response.from(s.update(id,r.contractName,r.description,r.status,r.rowVersion,actor));}
@PostMapping("/{id}/versions")public ResponseEntity<VersionResponse> createVersion(@PathVariable@Min(1)long id,@Valid@RequestBody CreateVersion r,@RequestHeader("X-Operator")@NotBlank@Size(max=100)String actor){var v=s.createVersion(id,r.semanticVersion,r.schemaStandard,r.schemaDocument,r.exampleDocument,r.compatibilityMode,actor);return ResponseEntity.created(URI.create("/control/v1/contracts/"+id+"/versions/"+v.id())).body(version(v));}@GetMapping("/{id}/versions")public List<VersionResponse> versions(@PathVariable@Min(1)long id){return s.versions(id).stream().map(this::version).toList();}@GetMapping("/{id}/versions/{versionId}")public VersionResponse version(@PathVariable@Min(1)long id,@PathVariable@Min(1)long versionId){return version(s.version(id,versionId));}@PostMapping("/{id}/versions/{versionId}:publish")public VersionResponse publish(@PathVariable@Min(1)long id,@PathVariable@Min(1)long versionId,@RequestHeader("X-Operator")@NotBlank@Size(max=100)String actor){return version(s.publish(id,versionId,actor));}
private VersionResponse version(CanonicalContractVersion v){return new VersionResponse(v.id(),v.contractId(),v.versionNo(),v.semanticVersion().toString(),v.schemaStandard(),read(v.schemaDocument()),read(v.exampleDocument()),v.compatibilityMode(),v.contentChecksum(),v.lifecycleStatus(),v.publishedAt(),v.createdAt());}private JsonNode read(String v){if(v==null)return null;try{return mapper.readTree(v);}catch(JsonProcessingException e){throw new IllegalStateException("Stored canonical contract JSON is invalid",e);}}
public record Create(@Positive long operationId,@NotBlank@Size(max=180)@Pattern(regexp="^[a-z][a-z0-9]*(?:[._-][a-z0-9]+)*$")String contractCode,@NotBlank@Size(max=200)String contractName,@NotNull ContractKind contractKind,@Size(max=1000)String description){}public record Update(@NotBlank@Size(max=200)String contractName,@Size(max=1000)String description,@NotNull CanonicalContractStatus status,@PositiveOrZero long rowVersion){}public record CreateVersion(@NotBlank@Size(max=32)@Pattern(regexp="^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-[0-9A-Za-z.-]+)?(?:\\+[0-9A-Za-z.-]+)?$")String semanticVersion,@NotNull SchemaStandard schemaStandard,@NotNull JsonNode schemaDocument,JsonNode exampleDocument,@NotNull CompatibilityMode compatibilityMode){}public record Response(long id,long operationId,String contractCode,String contractName,ContractKind contractKind,String description,CanonicalContractStatus status,long rowVersion,Instant createdAt,Instant updatedAt){static Response from(CanonicalContract c){return new Response(c.id(),c.operationId(),c.contractCode().value(),c.contractName(),c.contractKind(),c.description(),c.status(),c.rowVersion(),c.createdAt(),c.updatedAt());}}public record Page(List<Response>items,int page,int size,long totalElements){}public record VersionResponse(long id,long contractId,int versionNo,String semanticVersion,SchemaStandard schemaStandard,JsonNode schemaDocument,JsonNode exampleDocument,CompatibilityMode compatibilityMode,String contentChecksum,CanonicalContractLifecycleStatus lifecycleStatus,Instant publishedAt,Instant createdAt){}
}
